import React, { useState ,useEffect} from 'react';
import Art from './Art';
import Vibrant from "node-vibrant";
import content from '../content';

function componentToHex(c) {
    var hex = c.toString(16);
    return hex.length === 1 ? "0" + hex : hex;
}

function rgbToHex(r, g, b) {
    return "#" + componentToHex(r) + componentToHex(g) + componentToHex(b);
}

async function getPal(img){
    let colors = []
    let pal = new Vibrant(img)
    await pal.getPalette().then((palette) => {
        let dm = palette.DarkMuted
        colors.push(rgbToHex(dm.rgb[0],dm.rgb[1],dm.rgb[2]))
        let dv = palette.DarkVibrant
        colors.push(rgbToHex(dv.rgb[0],dv.rgb[1],dv.rgb[2]))
        let lm = palette.LightMuted
        colors.push(rgbToHex(lm.rgb[0],lm.rgb[1],lm.rgb[2]))
        let lv = palette.LightVibrant
        colors.push(rgbToHex(lv.rgb[0],lv.rgb[1],lv.rgb[2]))
        let m = palette.Muted
        colors.push(rgbToHex(m.rgb[0],m.rgb[1],m.rgb[2]))
        let v = palette.Vibrant
        colors.push(rgbToHex(v.rgb[0],v.rgb[1],v.rgb[2]))
        //console.log(rgbToHex(palette.DarkMuted.rgb[0],palette.DarkMuted.rgb[1],palette.DarkMuted.rgb[2]));

    });
    return colors; 
}


function Gallery() {

    const [state, setstate] = useState([])

    useEffect(() => {
        content.img.forEach(element => {
            setstate(oldArray => [...oldArray, getPal(element) ]);
            console.log(state);
        });

    }, [])


    return(
    <div className={"flex justify-center overflow-x-auto"}>
        {content.img.map((items, index) => {
                return (
                    <div  className={"m-4 inline-flex"} >
                        <Art src={items} pal={getPal(items)} key={index} />
                    </div>
                );
            })}
    </div>
    )
}

export default Gallery
